      "achados": [
        {
          "proposicao": "No caso analisado, os documentos de resposta à emergência citados não descreviam os recursos necessários para cada cenário acidental, de modo que o texto afirma não ser possível garantir sua disponibilidade.",
          "trechos": [
            "E7a180984424e0b6e:0:695"
          ],
          "condicoes": [
            "Referente ao PRE OU-ES, ao PMAE-EP e documentos correlatos examinados na investigação do FPSO CDSM."
          ],
          "limites": [
            "É achado documental do caso investigado.",
            "O trecho não identifica inventário completo de recursos nem critérios de suficiência."
          ]
        },
        {
          "proposicao": "A capacitação para lidar com grandes emergências da BW aparecia concentrada no IOM, enquanto a brigada tinha previsão de cursos específicos de combate a incêndio, sobrevivência e resgate, manobras de equipe, primeiros socorros e embarcações de resgate rápido.",
          "trechos": [
            "E7a180984424e0b6e:0:695",
            "E7a180984424e0b6e:695:1395"
          ],
          "condicoes": [
