            "Ee662aa37ac382fac:1395:2095",
            "Ee662aa37ac382fac:2095:2334"
          ],
          "condicoes": [
            "Na descrição geral da gestão de riscos do FPSO Cidade de São Mateus."
          ],
          "limites": [
            "O trecho é introdutório e não detalha metodologia, periodicidade ou critérios de atualização."
          ]
        }
      ]
